const failureDetail = 'The notebook service could not accept the document. Your writing is still available here. Retry when the connection returns. The field team can continue using the previous saved copy while this document waits to upload.';

export function mountSaveStatus(root, notebook) {
  const global = document.querySelector('#global-status');
  const notice = root.querySelector('#save-notice');
  const label = root.querySelector('#save-label');
  const detail = root.querySelector('#save-detail');
  const retry = root.querySelector('#retry');
  const footer = root.querySelector('.document-footer span:first-child');
  const render = () => {
    const status = notebook.saveState;
    if (status === 'failed') { global.hidden = false; global.textContent = 'The last save failed.'; }
    notice.hidden = status === 'idle';
    label.textContent = {failed:'Save failed', saving:'Saving', saved:'Saved'}[status] || '';
    detail.hidden = status !== 'failed'; detail.textContent = failureDetail;
    retry.hidden = status !== 'failed';
    footer.hidden = status === 'saving';
    footer.textContent = status === 'failed' ? 'Saved locally' : 'Saved locally';
  };
  root.querySelector('#save').onclick = () => notebook.save();
  retry.onclick = () => notebook.retry();
  notebook.subscribe(event => { if (['save','document'].includes(event)) render(); });
  render();
}
